[1215] = "분기",
-- b8e156bb English: Choose a category and search for a condition. Hidden removes it from pickers
--     without deleting its definition. Switch Condition controls its availability for automatic
--     rotation switching. Move To changes its category; order arrows arrange category entries.
--     Custom conditions can be edited, duplicated or deleted.
[1216] = "분류를 선택하고 조건을 검색하세요. 숨김은 정의를 삭제하지 않고 선택 목록에서만 제거합니다. 전환 조건은 자동 로테이션 전환에 사용할 수 있는지를 정합니다. 이동 위치는 분류를 바꾸고, 순서 화살표는 분류 내 항목을 정렬합니다. 사용자 조건은 편집, 복제, 삭제할 수 있습니다.",
-- 95e310bf English: Choose a current profile or enter a new profile name and create it. Copy
--     replaces the current profile’s settings; Reset restores defaults. Delete removes another
--     saved profile. Copy, Reset and Delete ask for confirmation.
[1217] = "현재 프로필을 선택하거나 새 프로필 이름을 입력해 생성하세요. 복사는 현재 프로필의 설정을 대체하고, 초기화는 기본값을 복원합니다. 삭제는 저장된 다른 프로필을 제거합니다. 복사, 초기화, 삭제는 확인을 요청합니다.",
-- 07c1af16 English: Choose an item set and edit its priority list. Global shares the set across
--     profiles. Move arrows change item priority. Bind item set picks up an available item for
--     placement on an action bar; Remove binding unlinks it. Reset restores a packaged set. Import
--     replaces its item list.
[1218] = "아이템 세트를 선택하고 우선순위 목록을 편집하세요. 전역은 세트를 모든 프로필에서 공유합니다. 이동 화살표로 아이템 우선순위를 바꿉니다. 아이템 세트 연결은 사용 가능한 아이템을 집어 행동 단축바에 놓을 수 있게 하고, 연결 제거는 연결을 해제합니다. 초기화는 기본 제공 세트를 복원합니다. 가져오기는 아이템 목록을 대체합니다.",
-- 584f475e English: Condition editor
-- Context: Title of the help window for the condition editor.
[1219] = "조건 편집기",
-- dae8a15b English: Description and attribution
-- Context: Heading in the help for the rotation metadata dialog: the description and author fields.
[1220] = "설명 및 제작자 정보",
-- 0bff7d0e English: Drag the title bar to move. Set Scale with the top-left slider; child windows
--     follow it. The question mark toggles Help. Close with X, Escape, or right-click in the
--     content area.
[1221] = "제목 표시줄을 끌어 이동합니다. 왼쪽 위 슬라이더로 크기 비율을 설정하면 하위 창도 따라갑니다. 물음표는 도움말을 켜고 끕니다. X, Escape 또는 내용 영역 오른쪽 클릭으로 닫습니다.",
-- b2fe791b English: Edit the description, author, realm, email, website and version. Source
--     citations remain separate from your attribution. Use changes updates the rotation draft;
--     Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values.
[1222] = "설명, 제작자, 서버, 이메일, 웹사이트, 버전을 편집하세요. 출처 표기는 제작자 정보와 별도로 유지됩니다. 변경 사항 사용은 로테이션 초안을 갱신하며, 저장하려면 로테이션을 적용하세요. 취소나 Escape는 이 창을 열 때의 값을 복원합니다.",
-- 0305e247 English: Expand an announcement to choose its action, event, channel and text. Spell
--     fields search the catalog; where the client has spell ranks, Use this exact spell rank limits
--     matching to the rank you chose. Enabled toggles the announcement. Add announcement creates a
--     new entry after an action is selected.
[1223] = "알림을 펼쳐 동작, 이벤트, 채널, 텍스트를 선택하세요. 주문 필드는 목록에서 검색하며, 클라이언트에 주문 등급이 있으면 ‘이 주문 등급만 사용’이 고른 등급만 일치하도록 제한합니다. 사용으로 알림을 켜고 끕니다. 알림 추가는 동작을 선택한 뒤 새 항목을 만듭니다.",
-- 2c02392e English: Groups and toggles
-- Context: Heading in help text explaining AND/OR/NOT groups and the If/Unless and Enabled/Disabled
--     toggles in the condition editor.
[1224] = "그룹 및 전환",
-- 3d69858e English: Help and saving
-- Context: Heading in help text describing the Help (question mark) button and how saving works
--     (Undo/Redo/Apply) in the editor.
[1225] = "도움말 및 저장",
-- 99855946 English: Move, copy and remove
[1226] = "이동, 복사 및 제거",
-- 9497b4fc English: Select an effect to edit its name, type and type-specific settings. The icon
--     previews it live. Sequence sections edit animation, color, pulse or custom frames in order.
--     Duplicate creates an independent effect. Import replaces the selected effect after
--     validation.
[1227] = "효과를 선택해 이름, 유형, 유형별 설정을 편집하세요. 아이콘으로 실시간 미리보기가 됩니다. 순서 섹션은 애니메이션, 색상, 맥동 또는 사용자 프레임을 차례로 편집합니다. 복제는 독립적인 효과를 만듭니다. 가져오기는 검증 후 선택한 효과를 대체합니다.",
-- 95b23356 English: These settings apply immediately. Press Enter or leave a text field to commit
--     it. Invalid text stays red and blocks navigation until corrected. Searchable selectors open
--     on click and filter as you type. Section headings collapse or expand their contents.
[1228] = "이 설정은 즉시 적용됩니다. Enter를 누르거나 텍스트 필드를 벗어나면 확정됩니다. 잘못된 텍스트는 빨간색으로 남으며 수정할 때까지 이동을 막습니다. 검색 가능한 선택 목록은 클릭하면 열리고 입력하는 대로 필터링됩니다. 섹션 제목을 클릭하면 내용을 접거나 펼칩니다.",
-- 00a767bc English: Unknown spell
-- Context: Placeholder name for a spell that cannot be found by ID (announcement list, reference
