-- %d #1: %d #1: how many selected cards are being dragged, e.g. 3
[1298] = "선택한 카드 %d개 이동",
-- 6c0b9d10 English: Duplicate selected cards
-- Context: Tooltip of a bulk button in the rotation/condition editor: duplicate every selected card
