-- 9e3bd238 English: Edit fields opens a graphical schema draft. Add, name, reorder or remove
--     fields, choose primitive or nested types, and edit nested fields. Apply stages the schema and
--     its field order. Advanced exposes the equivalent raw schema, parsed as data without executing
--     Lua.
[1548] = "필드 편집은 그래픽 스키마 초안을 엽니다. 필드를 추가, 이름 지정, 순서 변경, 제거하고, 기본 형식이나 중첩 형식을 선택하며, 중첩 필드를 편집하세요. 적용은 스키마와 필드 순서를 준비합니다. 고급은 같은 내용의 원시 스키마를 보여 주며, Lua를 실행하지 않고 데이터로 분석합니다.",
-- 5ed7c1f2 English: Decide whether this condition currently matches.
[1549] = "이 조건이 현재 일치하는지 판단합니다.",
-- cbb89125 English: The stored values for this condition.
[1550] = "이 조건에 저장된 값입니다.",
-- d02f326b English: Shared data for this evaluation cycle.
[1551] = "이번 평가 주기의 공유 데이터입니다.",
-- 5e32b652 English: Evaluation start time, in seconds from GetTime().
[1552] = "GetTime() 기준 초 단위 평가 시작 시각입니다.",
-- dbb95241 English: True matches; false or nil does not match.
[1553] = "true는 일치, false나 nil은 불일치입니다.",
-- 33035e0c English: Check whether the stored condition values are complete and valid.
[1554] = "저장된 조건 값이 완전하고 유효한지 확인합니다.",
-- bc51adc0 English: Rotation specialization scope.
[1555] = "로테이션 전문화 범위입니다.",
-- 0cb1ce78 English: True when the condition can be evaluated.
[1556] = "조건을 평가할 수 있으면 true입니다.",
-- 18eb8e30 English: Describe the condition in readable words.
[1557] = "조건을 읽기 쉬운 말로 설명합니다.",
-- 4e9300c4 English: The human-readable condition summary.
[1558] = "사람이 읽을 수 있는 조건 요약입니다.",
-- 7ea336df English: Build the controls used to edit this condition.
[1559] = "이 조건을 편집하는 컨트롤을 만듭니다.",
-- 2010cda9 English: The condition field container supplied by the UI adapter.
[1560] = "UI 어댑터가 제공하는 조건 필드 컨테이너입니다.",
-- 2209776b English: Add controls to the supplied container.
[1561] = "제공된 컨테이너에 컨트롤을 추가합니다.",
-- ca5a0eaf English: Build the help content for this condition.
[1562] = "이 조건의 도움말 내용을 만듭니다.",
-- a2731a25 English: The help container supplied by the UI adapter.
[1563] = "UI 어댑터가 제공하는 도움말 컨테이너입니다.",
-- 96bf1d1e English: Add help content to the supplied container.
[1564] = "제공된 컨테이너에 도움말 내용을 추가합니다.",
-- 6738aee6 English: Initialize resources when the condition is registered.
[1565] = "조건이 등록될 때 자원을 초기화합니다.",
-- 49e57f5b English: The condition identifier.
[1566] = "조건 식별자입니다.",
-- 46569f1f English: No return value is used.
[1567] = "반환값은 사용하지 않습니다.",
-- 95a1b634 English: Release resources when the condition is removed or replaced.
[1568] = "조건이 제거되거나 교체될 때 자원을 해제합니다.",
-- 7f816072 English: Arguments
