[1595] = "LuaWorkbench는 편집, 자동 완성, API 정보, 디버깅을 제공합니다. 디버그는 테스트 인수로 이 버퍼를 명시적으로 실행하며, 저장된 로테이션이나 실행 중인 콜백을 대체하지 않습니다.",
-- ac6ddfe4 English: Connected: embedded editing, completion, API knowledge and debugging.
[1596] = "연결됨: 내장 편집, 자동 완성, API 정보, 디버깅.",
-- e3b56b53 English: Review the dependency bundle before applying it.
[1597] = "적용하기 전에 의존성 묶음을 검토하세요.",
