[1758] = "검증 안 됨",
-- 0d6aeafd English: Client family: %s (%s)
-- %s #1: %s #1: the game client family, e.g. "Classic Era"
-- %s #2: %s #2: the compatibility status, "declared; unverified" or "unsupported" (translated), e.g. "unsupported"
[1759] = "클라이언트 계열: %s (%s)",
