[2224] = "nil인 레코드에 대한 정책, 칸 검증, 기능 또는 기본 호출 사용 불가 이유.",
-- 57d4e2a6 English: Policy, snapshot, identity or threat observation availability reason.
[2225] = "정책, 스냅샷, 식별 또는 위협 관찰 사용 불가 이유.",
-- 88172c69 English: Policy, token-validation or availability reason for a nil identity result.
[2226] = "nil인 식별 결과에 대한 정책, 토큰 검증 또는 사용 불가 이유.",
-- 41f7dc66 English: Policy, validation or availability reason for a nil health observation.
[2227] = "nil인 생명력 관찰에 대한 정책, 검증 또는 사용 불가 이유.",
-- cc67968e English: Policy, validation or availability reason for a nil snapshot.
[2228] = "nil인 스냅샷에 대한 정책, 검증 또는 사용 불가 이유.",
-- 84bacc88 English: Policy, validation or observation availability reason.
[2229] = "정책, 검증 또는 관찰 사용 불가 이유.",
-- 702b5d1d English: Policy, validation or required observation availability reason.
[2230] = "정책, 검증 또는 필수 관찰 사용 불가 이유.",
-- e3a0a3ce English: Positive integer glyph item ID stored by the condition; arrays, item-set keys
--     and spell IDs are not item references.
[2231] = "조건에 저장된 양의 정수 문양 아이템 ID. 배열, 아이템 세트 키, 주문 ID는 아이템 참조가 아닙니다.",
-- c7e5f035 English: Positive integer level, false for a known absent unit, or nil when unavailable.
[2232] = "양의 정수 레벨, 없는 것으로 알려진 유닛이면 false, 사용할 수 없으면 nil.",
-- 2ce665d6 English: Positive integer spell ID, not a spell-book slot.
[2233] = "주문서 칸이 아닌 양의 정수 주문 ID.",
-- 37be242f English: Positive item ID or native-recognized item name/link to classify.
[2234] = "분류할 양수 아이템 ID, 또는 게임이 인식하는 아이템 이름/링크.",
-- eac23024 English: Predicate that validates the proposed spell value.
[2235] = "제안된 주문 값을 검증하는 조건식.",
-- b7acadb2 English: Present GUID, false for known absence, or nil when unavailable.
[2236] = "있는 유닛의 GUID, 없는 것으로 알려지면 false, 사용할 수 없으면 nil.",
-- 5825055c English: Provider, validation or observation availability reason.
[2237] = "제공자, 검증 또는 관찰 사용 불가 이유.",
-- e78c7309 English: Query, policy or observation availability reason.
[2238] = "조회, 정책 또는 관찰 사용 불가 이유.",
-- b79b336b English: RM comparison operator identifier; missing labels use the operator placeholder.
[2239] = "RM 비교 연산자 식별자. 이름표가 없으면 연산자 자리 표시자를 사용합니다.",
-- 505c9dde English: RM operator identifier.
[2240] = "RM 연산자 식별자.",
-- a3bcccb3 English: Range record with applicable and, when applicable, inRange; nil when
