[2763] = "해제 가능",
-- fe483cd0 English: your own %s
-- Context: Part of a buff or debuff summary: %s is the buff/debuff name, giving 'your own Renew'.
--     Used when the 'only my own' option is on.
-- %s #1: %s #1: the buff or debuff name, e.g. "Power Word: Fortitude" (the sentence reads "your own" followed by it)
[2764] = "자신의 %s",
-- fd008b93 English: {unit} {{!have|do not have}} {aura}
[2765] = "{unit}: {aura} {{!있음|없음}}",
-- c957b45d English: {unit} {{!has|does not have}} {aura}
[2766] = "{unit}: {aura} {{!있음|없음}}",
-- fcebc215 English: {unit} {{!have|do not have}} {aura} where {remaining} {comparison} {duration}
[2767] = "{unit}: {aura} {{!있음|없음}}, 조건: {remaining} {comparison} {duration}",
-- 62276ac5 English: {unit} {{!has|does not have}} {aura} where {remaining} {comparison} {duration}
[2768] = "{unit}: {aura} {{!있음|없음}}, 조건: {remaining} {comparison} {duration}",
