[2769] = "{unit}에 걸린 {aura} 중첩 수가 {comparison} {quantity}",
-- 0a2d00cc English: that is dispellable
-- Context: Phrase appended to a debuff summary when the Dispellable option is on, e.g. '... of type
--     Magic that is dispellable'.
[2770] = "해제 가능한",
